package com.ajdar.magnetometerrecorder;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.hardware.*;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;import java.nio.charset.*;import java.text.*;

public class PlotV51Activity extends Activity implements SensorEventListener{
 static final int CSV=6001; SensorManager sm; Sensor mag,la,gy; TextView stat,read; EditText sid,note; Spinner rate; Button start,stop,save; P px,py,pz,pa; Handler h=new Handler(Looper.getMainLooper()); boolean rec=false; long t0=-1,last=-1,wall=-1; float bx,by,bz,ba,ax=Float.NaN,ay=Float.NaN,az=Float.NaN,gx=Float.NaN,gyv=Float.NaN,gz=Float.NaN; int ma=0,aa=0,ga=0; ArrayList<S> rows=new ArrayList<>();
 Runnable tick=new Runnable(){public void run(){upd();h.postDelayed(this,500);}};
 public void onCreate(Bundle b){super.onCreate(b);ui();}
 public void onResume(){super.onResume();h.post(tick);} public void onPause(){super.onPause();h.removeCallbacks(tick);if(sm!=null&&!rec)sm.unregisterListener(this);}
 void ui(){ScrollView sv=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(14),dp(14),dp(14),dp(18));r.setBackgroundColor(Color.rgb(248,250,252));sv.addView(r);TextView title=new TextView(this);title.setText("MAG Recorder v6");title.setTextSize(25);title.setTextColor(Color.rgb(20,28,45));r.addView(title);TextView sub=new TextView(this);sub.setText("MAG plots + CSV for magnetometer, linear acceleration and gyroscope.");sub.setTextSize(13);sub.setTextColor(Color.rgb(70,80,100));r.addView(sub);sid=new EditText(this);sid.setHint("Session ID, e.g. S01_rest_supine");sid.setSingleLine(true);r.addView(sid);note=new EditText(this);note.setHint("Notes: phone position, posture, reference device");note.setMinLines(2);r.addView(note);rate=new Spinner(this);String[] m={"50 Hz","100 Hz","200 Hz","Maximum"};ArrayAdapter<String>a=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,m);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);rate.setAdapter(a);rate.setSelection(2);r.addView(rate);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);start=new Button(this);start.setText("Start");stop=new Button(this);stop.setText("Stop");stop.setEnabled(false);save=new Button(this);save.setText("Save CSV");save.setEnabled(false);row.addView(start,new LinearLayout.LayoutParams(0,-2,1));row.addView(stop,new LinearLayout.LayoutParams(0,-2,1));row.addView(save,new LinearLayout.LayoutParams(0,-2,1));r.addView(row);stat=new TextView(this);stat.setText("x-axis=time(s), y-axis=magnetic field(uT). Linear ACC is gravity-removed.");stat.setTextSize(14);r.addView(stat);read=new TextView(this);read.setTextSize(15);r.addView(read);px=new P(this,"Bx vs time","Bx(uT)",Color.rgb(190,32,38));py=new P(this,"By vs time","By(uT)",Color.rgb(0,135,70));pz=new P(this,"Bz vs time","Bz(uT)",Color.rgb(30,92,180));pa=new P(this,"|B| vs time","|B|(uT)",Color.rgb(120,48,150));r.addView(px,sz());r.addView(py,sz());r.addView(pz,sz());r.addView(pa,sz());TextView inf=new TextView(this);inf.setText("App version: 6.0 | CSV includes MAG + linear ACC + GYRO + dt_ms.");inf.setTextSize(12);r.addView(inf);setContentView(sv);start.setOnClickListener(v->go());stop.setOnClickListener(v->halt());save.setOnClickListener(v->saveCsv());}
 boolean sensors(){if(sm!=null&&mag!=null)return true;sm=(SensorManager)getSystemService(SENSOR_SERVICE);if(sm==null){stat.setText("Sensor service unavailable");return false;}mag=sm.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD);if(mag==null)mag=sm.getDefaultSensor(Sensor.TYPE_MAGNETIC_FIELD_UNCALIBRATED);la=sm.getDefaultSensor(Sensor.TYPE_LINEAR_ACCELERATION);gy=sm.getDefaultSensor(Sensor.TYPE_GYROSCOPE);if(mag==null){stat.setText("No magnetometer found");return false;}return true;}
 int del(){int p=rate.getSelectedItemPosition();if(p==0)return 20000;if(p==1)return 10000;if(p==2)return 5000;return SensorManager.SENSOR_DELAY_FASTEST;} String mode(){return String.valueOf(rate.getSelectedItem());}
 void go(){if(!sensors())return;rows.clear();px.cl();py.cl();pz.cl();pa.cl();t0=-1;last=-1;wall=System.currentTimeMillis();rec=true;start.setEnabled(false);stop.setEnabled(true);save.setEnabled(false);sid.setEnabled(false);note.setEnabled(false);rate.setEnabled(false);int d=del();sm.unregisterListener(this);boolean ok=sm.registerListener(this,mag,d);if(la!=null)sm.registerListener(this,la,d);if(gy!=null)sm.registerListener(this,gy,d);if(!ok){stat.setText("Could not start magnetometer");halt();return;}stat.setText("Recording MAG + linear ACC + GYRO at "+mode());}
 void halt(){rec=false;if(sm!=null)sm.unregisterListener(this);start.setEnabled(true);stop.setEnabled(false);save.setEnabled(rows.size()>0);sid.setEnabled(true);note.setEnabled(true);rate.setEnabled(true);stat.setText("Stopped. Samples: "+rows.size()+". Press Save CSV.");}
 public void onSensorChanged(SensorEvent e){if(e==null||e.values==null||e.values.length<3)return;int t=e.sensor.getType();if(t==Sensor.TYPE_LINEAR_ACCELERATION){ax=e.values[0];ay=e.values[1];az=e.values[2];return;}if(t==Sensor.TYPE_GYROSCOPE){gx=e.values[0];gyv=e.values[1];gz=e.values[2];return;}if(t!=Sensor.TYPE_MAGNETIC_FIELD&&t!=Sensor.TYPE_MAGNETIC_FIELD_UNCALIBRATED)return;if(t0<0)t0=e.timestamp;float ts=(e.timestamp-t0)/1000000000f;float dt=last>0?(e.timestamp-last)/1000000f:Float.NaN;last=e.timestamp;bx=e.values[0];by=e.values[1];bz=e.values[2];ba=(float)Math.sqrt(bx*bx+by*by+bz*bz);if(rec){rows.add(new S(ts,e.timestamp,bx,by,bz,ba,ax,ay,az,gx,gyv,gz,ma,aa,ga,dt));px.add(ts,bx);py.add(ts,by);pz.add(ts,bz);pa.add(ts,ba);}}
 public void onAccuracyChanged(Sensor s,int a){if(s==null)return;int t=s.getType();if(t==Sensor.TYPE_LINEAR_ACCELERATION)aa=a;else if(t==Sensor.TYPE_GYROSCOPE)ga=a;else ma=a;}
 void upd(){float dur=t0>=0&&last>t0?(last-t0)/1000000000f:0;float fs=dur>0&&rows.size()>1?(rows.size()-1)/dur:0;read.setText(String.format(Locale.US,"MAG Bx %.2f By %.2f Bz %.2f |B| %.2f uT\nACC Ax %.3f Ay %.3f Az %.3f m/s2\nGYRO Gx %.3f Gy %.3f Gz %.3f rad/s\nSamples %d Duration %.1f s MAG fs %.1f Hz Mode %s",bx,by,bz,ba,ax,ay,az,gx,gyv,gz,rows.size(),dur,fs,mode()));}
 void saveCsv(){if(rows.isEmpty()){Toast.makeText(this,"No samples to save",Toast.LENGTH_SHORT).show();return;}String id=clean(sid.getText().toString());if(id.length()==0)id="session";String st=new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date(wall>0?wall:System.currentTimeMillis()));Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"mag_v6_"+id+"_"+st+".csv");startActivityForResult(i,CSV);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==CSV&&c==RESULT_OK&&d!=null&&d.getData()!=null){try{OutputStream o=getContentResolver().openOutputStream(d.getData());BufferedWriter w=new BufferedWriter(new OutputStreamWriter(o,StandardCharsets.UTF_8));w.write(csvText());w.close();Toast.makeText(this,"CSV saved",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Save failed: "+e.getMessage(),Toast.LENGTH_LONG).show();}}}
 String csvText(){StringBuilder sb=new StringBuilder();sb.append("# app_version,6.0\n# sampling_mode,").append(mode()).append("\n# requested_delay_us,").append(del()).append("\n# subject,").append(csv(sid.getText().toString())).append("\n# notes,").append(csv(note.getText().toString())).append("\n# device,").append(csv(Build.MANUFACTURER+" "+Build.MODEL)).append("\n# sample_count,").append(rows.size()).append("\n");sb.append("time_s,mag_timestamp_ns,system_start_unix_ms,Bx_uT,By_uT,Bz_uT,B_abs_uT,linacc_x_mps2,linacc_y_mps2,linacc_z_mps2,gyro_x_rad_s,gyro_y_rad_s,gyro_z_rad_s,mag_accuracy,linacc_accuracy,gyro_accuracy,dt_ms\n");for(S s:rows)sb.append(String.format(Locale.US,"%.9f,%d,%d,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%.9f,%d,%d,%d,%.6f\n",s.t,s.ns,wall,s.bx,s.by,s.bz,s.ba,s.ax,s.ay,s.az,s.gx,s.gy,s.gz,s.ma,s.aa,s.ga,s.dt));return sb.toString();}
 static String clean(String s){return s==null?"":s.trim().replaceAll("[^A-Za-z0-9_.-]+","_");} static String csv(String s){if(s==null)return"";boolean q=s.contains(",")||s.contains("\n")||s.contains("\"");String e=s.replace("\"","\"\"").replace("\r"," ").replace("\n"," ");return q?"\""+e+"\"":e;} int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} LinearLayout.LayoutParams sz(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(210));p.setMargins(0,dp(8),0,dp(8));return p;}
 static class S{float t,bx,by,bz,ba,ax,ay,az,gx,gy,gz,dt;long ns;int ma,aa,ga;S(float t,long ns,float bx,float by,float bz,float ba,float ax,float ay,float az,float gx,float gy,float gz,int ma,int aa,int ga,float dt){this.t=t;this.ns=ns;this.bx=bx;this.by=by;this.bz=bz;this.ba=ba;this.ax=ax;this.ay=ay;this.az=az;this.gx=gx;this.gy=gy;this.gz=gz;this.ma=ma;this.aa=aa;this.ga=ga;this.dt=dt;}}
 public static class P extends View{ArrayDeque<float[]>q=new ArrayDeque<>();Paint bg=new Paint(1),b=new Paint(1),g=new Paint(1),tx=new Paint(1),ln=new Paint(1);String title,ylab;P(Context c,String t,String y,int col){super(c);title=t;ylab=y;bg.setColor(Color.WHITE);b.setColor(Color.rgb(75,85,99));b.setStyle(Paint.Style.STROKE);b.setStrokeWidth(2);g.setColor(Color.rgb(226,232,240));tx.setColor(Color.rgb(55,65,81));tx.setTextSize(21);ln.setColor(col);ln.setStrokeWidth(3);setBackgroundColor(Color.rgb(248,250,252));}void cl(){q.clear();invalidate();}void add(float t,float v){q.add(new float[]{t,v});while(q.size()>700)q.removeFirst();postInvalidateOnAnimation();}protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();float l=78,T=34,r=w-18,bt=h-46;c.drawRect(0,0,w,h,bg);c.drawText(title,l,25,tx);c.drawRect(l,T,r,bt,b);for(int i=1;i<4;i++){float yy=T+i*(bt-T)/4;c.drawLine(l,yy,r,yy,g);}c.drawText(ylab,4,T+18,tx);c.drawText("time (s)",r-92,h-12,tx);if(q.size()<2){c.drawText("Waiting for samples...",l+12,T+44,tx);return;}float t0=q.peekFirst()[0],t1=q.peekLast()[0];if(t1<=t0)t1=t0+1;float mn=Float.POSITIVE_INFINITY,mx=Float.NEGATIVE_INFINITY;for(float[]p:q){float v=p[1];if(!Float.isNaN(v)&&!Float.isInfinite(v)){mn=Math.min(mn,v);mx=Math.max(mx,v);}}if(Math.abs(mx-mn)<1e-6){mn-=1;mx+=1;}float pad=.1f*(mx-mn);mn-=pad;mx+=pad;c.drawText(String.format(Locale.US,"%.1f",mx),4,T+12,tx);c.drawText(String.format(Locale.US,"%.1f",mn),4,bt,tx);c.drawText(String.format(Locale.US,"%.1fs",t0),l,h-12,tx);c.drawText(String.format(Locale.US,"%.1fs",t1),r-65,h-12,tx);Float lx=null,ly=null;for(float[]p:q){float x=l+(r-l)*(p[0]-t0)/(t1-t0);float y=bt-(bt-T)*(p[1]-mn)/(mx-mn);if(lx!=null)c.drawLine(lx,ly,x,y,ln);lx=x;ly=y;}}}
}